private fun TracePathNode.unwrapBoundary(previous: TracePathNode?): TracePathNode {
    val statement = statement
    if (statement !is JMethodBoundaryInst) return this

    val instructions = statement.location.method.instList.instructions
    val previousStatement = previous?.statement?.takeIf { it.location.method == statement.location.method }
    val real = when (statement) {
        is JMethodEnterInst -> instructions.first()
        is JMethodExitNormalInst -> previousStatement as? JIRReturnInst
            ?: instructions.lastOrNull { it is JIRReturnInst }
        is JMethodExitExceptionalInst -> previousStatement as? JIRThrowInst
            ?: instructions.lastOrNull { it is JIRThrowInst }
    } ?: return this

    return copy(statement = real)

override fun toVulnerabilities(report: Report): List<VulnerabilityWithTrace> {
    logger.info { "Bidi analysis: ${report.entries.size} reported sink identities" }
    return report.entries.map { entry ->
        val descriptor = entry.descriptor
        val rule = descriptor.rule
        val node = TaintSinkTracker.TaintVulnerabilityRuleNode.Unconditional(descriptor.representativeMethodKey)
        VulnerabilityWithTrace(TaintSinkTracker.TaintVulnerability(descriptor.key.statement, rule.id,
            hashMapOf(rule to node)), TracePathGenerationResult.Simple)
    }
}

override fun sinkRulesForMethodExit(
    method: CommonMethod,
    statement: CommonInst,
    fact: FactAp?,
    initialFacts: Set<InitialFactAp>?,
    allRelevant: Boolean
): Iterable<TaintMethodExitSink> {
    if (method !is JIRMethod || !method.isSpringControllerMethod()) {
        return base.sinkRulesForMethodExit(method, statement, fact, initialFacts, allRelevant)
    }

    val allBaseRules = base.sinkRulesForMethodExit(method, statement, fact, initialFacts = null, allRelevant)
    return allBaseRules.map { unfoldSpringExitObject(it) }
}

private fun unfoldSpringExitObject(rule: TaintMethodExitSink): TaintMethodExitSink =
    rule.copy(condition = unfoldObjectContainsMark(position = Result, rule.condition))

private fun unfoldObjectContainsMark(position: Position, condition: Condition): Condition =
    condition.accept(ContainsMarkRewriter(position))

fun exitRules(interp: JIRInterpreter, entry: JIRMethodEntry, key: MethodKey,
              exit: CommonInst, entryRules: RuleStatement,
              aliasAnalysis: JIRLocalAliasAnalysis? = entry.aliasAnalysis,
              potentialUnknownAliases: Boolean = false, view: RuleView = RuleView.FULL): ExitRules {
    val normal = when (exit) {
        is JMethodExitNormalInst -> true
        is JMethodExitExceptionalInst -> false
        else -> error("Not a boundary exit: $exit")
    }
    val forms = interp.ruleForms(view, exceptional = !normal)
    val method = key.method as JIRMethod
    val rewriter = calleeRewriter(interp, aliasAnalysis, method, exit, potentialUnknownAliases)
    val builder = MicroEdgeBuilder().apply { keepZero() }
    val form = FormKey(interp.entries.formOwner, method, null, exit)
    for ((ordinal, rule) in interp.rules.exitSourceRulesForMethod(method, exit, fact = null).withIndex()) {
        if (!forms.valid(rule)) continue
        val predicate = forms.source(builder, rule, RuleOccurrenceId(form, RuleKind.EXIT_SOURCE, rule.ruleOrdinal(ordinal)),
            forms.rewriteSourceOrSink(rule, rewriter))
        predicate.leaves.forEach { builder.keep(it.fact.base) }
    }
    val sinks = interp.rules.sinkRulesForMethodExit(method, exit, fact = null, initialFacts = null)
        .withIndex().flatMap { (ordinal, rule) ->
            if (!forms.valid(rule)) emptyList() else forms.sinks(rule, forms.rewriteSourceOrSink(rule, rewriter),
                RuleOccurrenceId(form, RuleKind.EXIT_SINK, rule.ruleOrdinal(ordinal)))
        }
    forms.sinkInputs(sinks).forEach(builder::staticOperation)
    return ExitRules(RuleStatement(builder.build(), genSummary(sinks), sinks),
        globalStateDrop = normal && sinks.isNotEmpty(),
        entryMarks = if (normal) entryMarks(entryRules) else emptySet())
}

